describe('Dashboard Sidebar Responsive Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
    cy.viewport('macbook-15');
  });

  it('should display sidebar navigation on desktop viewport', () => {
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="sidebar"]').should('have.css', 'left', '0px');

    cy.get('[data-testid="nav-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="nav-item"]').first().should('be.visible');

    cy.get('[data-testid="bottom-nav"]').should('not.exist');
  });

  it('should transform sidebar to bottom nav on mobile viewport', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="sidebar"]').should('not.be.visible');
    cy.get('[data-testid="bottom-nav"]').should('be.visible');
    cy.get('[data-testid="bottom-nav"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="bottom-nav"]').should('have.css', 'bottom', '0px');

    cy.get('[data-testid="bottom-nav-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="bottom-nav-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
  });

  it('should maintain navigation functionality in bottom nav', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="bottom-nav-item"]').contains('Dashboard').click();
    cy.url().should('include', '/dashboard');

    cy.get('[data-testid="bottom-nav-item"]').contains('Settings').click();
    cy.url().should('include', '/settings');
  });

  it('should properly transition between desktop and mobile viewports', () => {
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="bottom-nav"]').should('not.exist');

    cy.viewport('iphone-12');
    cy.get('[data-testid="sidebar"]').should('not.be.visible');
    cy.get('[data-testid="bottom-nav"]').should('be.visible');

    cy.viewport('ipad-2');
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="bottom-nav"]').should('not.exist');
  });

  it('should handle bottom nav with many items on mobile', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="bottom-nav"]').should('be.visible');
    cy.get('[data-testid="bottom-nav-item"]').should('have.length.greaterThan', 3);

    cy.get('[data-testid="bottom-nav"]').should('have.css', 'overflow-x', 'auto');

    cy.get('[data-testid="bottom-nav-item"]').last().scrollIntoView();
    cy.get('[data-testid="bottom-nav-item"]').last().should('be.visible');
  });

  it('should preserve active navigation state in bottom nav', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="bottom-nav-item"]').contains('Profile').click();
    cy.get('[data-testid="bottom-nav-item"]').contains('Profile').parent().should('have.class', 'active');

    cy.reload();
    cy.get('[data-testid="bottom-nav-item"]').contains('Profile').parent().should('have.class', 'active');
  });

  it('should not overlap content with bottom nav on mobile', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="main-content"]').then(($content) => {
      const contentBottom = $content[0].getBoundingClientRect().bottom;
      cy.get('[data-testid="bottom-nav"]').then(($nav) => {
        const navTop = $nav[0].getBoundingClientRect().top;
        expect(contentBottom).to.be.lessThan(navTop);
      });
    });
  });

  it('should handle edge case of tablet viewport with medium screen', () => {
    cy.viewport('ipad-mini');

    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="bottom-nav"]').should('not.exist');

    cy.get('[data-testid="sidebar"]').should('have.css', 'width');
    const sidebarWidth = cy.get('[data-testid="sidebar"]').invoke('width');
    sidebarWidth.should('be.greaterThan', 0);
  });
});
